# typed: true
# frozen_string_literal: true

module GitRPC
  class Backend
    # Internal: Load the contents of a cache file whose content was generated by
    # marshalling and compressing a Ruby data structure.
    #
    # filename - String path to the cache file relative to the repository root.
    #
    # Returns the unmarshalled content of the cache, or nil if the read
    # operation fails.
    def load_cache_file(filename)
      Marshal.load(
        Zlib::Inflate.inflate(
          fs_read(filename)
        )
      )
    rescue GitRPC::SystemError, ::Zlib::DataError, ::Zlib::BufError, TypeError
      nil
    end

    # Internal: Write a cache file by first marshalling its contents, then
    # compressing those contents with zlib.
    #
    # filename - String path to the cache file relative to the repository root.
    # data     - The content to cache.
    #
    # Returns nothing.
    def write_cache_file(filename, data)
      fs_write(
        filename,
        Zlib::Deflate.deflate(
          Marshal.dump(data)
        )
      )
    end
  end
end
